<div id="infobar-settings-sidebar-customer" class="infobar-settings-sidebar">
    <div class="infobar-settings-sidebar-head d-flex w-100 justify-content-between">
        <h4 id="exampleModalCenterTitle"><span id="customer_title">Add</span>&nbsp;<lang class="lang_customer_title">
                Customer</lang>
        </h4>
        <a href="javascript:void(0)" class="infobar-settings-close" data-id="customer">
            <img src="static/images/svg-icon/close.svg" class="img-fluid menu-hamburger-close" alt="close" loading="lazy" decoding="async">
        </a>
    </div>
    <div class="infobar-settings-sidebar-body">
        <div class="custom-mode-setting loader-customer">
            <form id='customer_add_form'>
                <div class="form-row">
                    <div class="form-group col-md-12">
                        <label for="customer_name">
                            <lang class="lang_name_title"> Name </lang>
                            <span class="text-danger">*</span>
                        </label>
                        <input type="text" class="form-control border-control customer-trigger" name="name"
                               id="customer_name" minlength="3" maxlength="250" placeholder="Enter the name" required>
                        <input type="hidden" name="id" id="customer_id" class="customer-trigger">
                    </div>
                </div>
                <div class="form-row">
                    <div class="form-group col-md-12">
                        <label for="customer_phone">
                            <lang class="lang_phone_title"> Phone </lang>
                        </label>
                        <input type="tel" class="form-control border-control customer-trigger allow_phone_validate"
                               name="phone" id="customer_phone" minlength="3" maxlength="20" placeholder="Enter the phone">
                    </div>
                </div>
                <div class="form-row">
                    <div class="form-group col-md-12">
                        <label for="customer_category">
                            <lang class="lang_choosecategory_title"> Category </lang>
                        </label>
                        <select id='customer_category' name="customer_category" style='width: 200px;' class="select2 customer_category">
                        </select> 
                    </div>
                </div>
                <div class="form-row">
                    <div class="form-group col-md-12">
                        <label for="customer_referrer_name">
                            <lang class="lang_choosecustomerReferral_title"> Referral customer </lang>
                        </label>
                        <input type="text" class="form-control" id="customer_referrer_name" name="customer_referrer_name" maxlength="50" placeholder="Choose a referrer" autocomplete="off">
                        <input type="hidden" name="customer_referrer_id" id="customer_referrer_id">
                    </div>
                </div>
                <div class="form-row">
                    <div class="form-group col-md-12">
                        <label for="customer_email">
                            <lang class="lang_email_title"> Email </lang>
                        </label>
                        <input type="email" class="form-control border-control customer-trigger" name="email"
                               id="customer_email" maxlength="50" placeholder="Enter the email">
                    </div>
                </div>
                <div class="form-row">
                    <div class="form-group col-md-12">
                        <label for="customer_address">
                            <lang class="lang_address_title"> Address </lang>
                        </label>
                        <textarea name="address" id="customer_address"
                                  class="form-control border-control customer-trigger" minlength="3" maxlength="500"
                                  placeholder="Enter the address"></textarea>
                    </div>
                </div>
                <div class="form-row">
                    <div class="form-group col-md-12">
                        <label for="customer_city">
                            <lang class="lang_city_title"> City </lang>
                        </label>
                        <input type="text" name="city" class="form-control border-control customer-trigger"
                               id="customer_city" maxlength="20" placeholder="Enter the city">
                    </div>
                </div>
                <div class="form-row">
                    <div class="form-group col-md-6">
                        <label for="customer_country">
                            <lang class="lang_country_title"> Country</lang>
                        </label>
                        <select class="select2 setCountry" name="country" data-page="customer_country"
                                id="customer_country"></select>
                    </div>
                    <div class="form-group col-md-6">
                        <label for="customer_state">
                            <lang class="lang_state_title"> State </lang>
                        </label>
                        <select class="select2 setState" name="state" data-page="customer_state"
                                id="customer_state"></select>
                    </div>
                </div>                
                <div class="form-row">
                    <div class="form-group col-md-12">
                        <input type="checkbox" class="custom-control-input" id="partial_balance" name="partial_balance">
                        <label class="custom-control-label" for="partial_balance">
                            Allow credit (pay later)
                        </label>
                        <small class="form-text text-muted">Let this customer buy on credit and settle the balance later.</small>
                    </div>
                </div>

                <div class="accordion m-b-10 indian-gstr" id="accordionCustomerExample">
                    <div class="card">
                        <div class="card-header" id="headingCustomerOne">
                            <h2 class="mb-0">
                                <button class="btn btn-link collapsed" type="button" data-toggle="collapse"
                                        data-target="#collapseCustomerOne" aria-expanded="false"
                                        aria-controls="collapseCustomerOne">
                                    <lang class="lang_gstfield"> GST Fields </lang>
                                    <span data-toggle="tooltip" data-placement="top" title=""
                                          data-original-title="customer gst fields">
                                        <i class="feather icon-help-circle"></i>
                                    </span>
                                </button>
                            </h2>
                        </div>
                        <div id="collapseCustomerOne" class="collapse" aria-labelledby="headingCustomerOne"
                             data-parent="#accordionCustomerExample">
                            <div class="card-body">
                                <div class="form-row">
                                    <div class="form-group col-md-12">
                                        <label for="customer_gst_type">
                                            <lang class="lang_supplier_gsttype_title"> GST Type </lang>
                                        </label>
                                        <select class="custom-select border-control" id="customer_gst_type"
                                                name="gst_type" onchange="PosnicPro.customers.gstFields();">
                                            <option value="consumer" selected>Unregisterd - consumer
                                            </option>
                                            <option value="regular">Registered - Regular
                                            </option>
                                            <option value="composite">Registered - Composite
                                            </option>
                                        </select>
                                    </div>
                                </div>
                                <div class="form-row customer-gstr-number" style="display:none;">
                                    <div class="form-group col-md-12">
                                        <label for="customer_gstin_number">
                                            <lang class="lang_supplier_gstin_number"> GSTIN Number <span
                                                    class="text-danger">*</span></lang>
                                        </label>
                                        <input type="text" class="form-control border-control" name="gstin_number"
                                               id="customer_gstin_number" minlength="15" maxlength="15"
                                               placeholder="Enter the GSTIN" autocomplete="off" required>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <div class="form-row">
                    <div class="form-group col-md-12">
                        <div class="pull-right">
                            <button type="button" class="btn btn-outline-secondary infobar-settings-reset"
                                    id="customer_reset" onclick="PosnicPro.customers.customerClearForm();"><i
                                    class="feather icon-refresh-ccw mr-2"></i>
                                <lang class="lang_clear_title"> Clear</lang>
                            </button>
                            <button type="button"
                                    class="btn btn-outline-secondary infobar-settings-reset customer_edit_reset"
                                    id="customer_edit_reset" onclick="PosnicPro.customers.resetEditButton(this.id);"><i
                                    class="feather icon-refresh-ccw mr-2"></i>
                                <lang class="lang_reset_title"> Reset</lang>
                            </button>
                            <button type="button" class="btn btn-outline-danger infobar-settings-close"
                                    data-id="customer">
                                <i class="feather icon-x-circle mr-2"></i>
                                <lang class="lang_close_title"> Close</lang>
                            </button>
                            <button type="submit" class="btn btn-outline-primary" id="customerSubmitForm">
                                <i class="feather icon-save mr-2"></i>
                                <span id="customer_button_title">
                                    <lang class="lang_save_title">Save</lang>
                                </span>
                            </button>
                        </div>
                    </div>
                </div>
                <div class="form-row" id="show_last_created_customer" style="display:none;">
                    <div class="form-group col-md-12">
                        <div class="pull-right">
                            <h6>Saved a customer. <a href="#" id="last_created_customer">Open it</a></h6>
                        </div>
                    </div>
                </div>
            </form>
        </div>
    </div>
</div>

